<script setup>
import { Head, Link, router, usePage } from '@inertiajs/vue3'; import AppLayout from '../../Layouts/AppLayout.vue'; defineProps({cart:Object}); const page=usePage(); const money=v=>new Intl.NumberFormat('en-TZ',{style:'currency',currency:page.props.store.currency,maximumFractionDigits:0}).format(v||0); const update=(p,q)=>router.patch(`/cart/${p.slug}`,{quantity:Number(q)},{preserveScroll:true}); const remove=p=>router.delete(`/cart/${p.slug}`,{preserveScroll:true});
</script><template><AppLayout><Head title="Shopping Cart"><meta head-key="robots" name="robots" content="noindex,nofollow" /></Head><section class="container-shell py-10"><h1 class="text-3xl font-black">Shopping cart</h1><div v-if="cart.items.length" class="mt-8 grid gap-8 lg:grid-cols-[1fr_360px]"><div class="space-y-4"><article v-for="line in cart.items" :key="line.product.id" class="card flex flex-col gap-4 p-4 sm:flex-row sm:items-center"><img :src="line.product.image_url" :alt="line.product.name" class="h-28 w-28 rounded-[10px] bg-slate-100 object-cover"><div class="min-w-0 flex-1"><Link :href="`/products/${line.product.slug}`" class="font-extrabold text-slate-950 hover:text-prinx-600">{{line.product.name}}</Link><p class="mt-1 text-xs text-slate-500">SKU: {{line.product.sku}}</p><p class="mt-2 font-bold">{{money(line.unit_price)}}</p></div><div class="flex items-center gap-3"><input :value="line.quantity" type="number" min="0" :max="line.product.track_stock?line.product.stock_quantity:99" class="input w-20 text-center" @change="update(line.product,$event.target.value)"><button class="text-sm font-bold text-red-600" @click="remove(line.product)">Remove</button></div><div class="w-32 text-right font-black">{{money(line.line_total)}}</div></article></div><aside class="card h-fit p-6"><h2 class="text-xl font-black">Order summary</h2><div class="mt-5 space-y-3 text-sm"><div class="flex justify-between"><span class="text-slate-500">Subtotal</span><b>{{money(cart.subtotal)}}</b></div><div class="flex justify-between"><span class="text-slate-500">Shipping</span><b>{{cart.shipping?money(cart.shipping):'Confirmed later'}}</b></div><div class="border-t border-slate-200 pt-4 flex justify-between text-lg"><span class="font-extrabold">Total</span><b>{{money(cart.total)}}</b></div></div><Link href="/checkout" class="btn-primary mt-6 w-full py-3">Continue to checkout</Link><Link href="/shop" class="btn-light mt-3 w-full">Continue shopping</Link></aside></div><div v-else class="card mt-8 py-20 text-center"><img src="/assets/accessory.svg" class="mx-auto h-28 w-28" alt="Empty cart"><h2 class="mt-5 text-xl font-black">Your cart is empty</h2><p class="mt-2 text-sm text-slate-500">Browse the catalogue and add products to your cart.</p><Link href="/shop" class="btn-primary mt-5">Start shopping</Link></div></section></AppLayout></template>
